package com.lynx.core.staff;

import org.bukkit.Bukkit; import org.bukkit.Material; import org.bukkit.entity.Player; import org.bukkit.inventory.*; import java.util.*; import java.util.concurrent.ConcurrentHashMap;

public final class StaffManager { private static StaffManager instance; private final Set<UUID> modMode=Collections.newSetFromMap(new ConcurrentHashMap<UUID,Boolean>()); private final Set<UUID> frozen=Collections.newSetFromMap(new ConcurrentHashMap<UUID,Boolean>()); private final Map<UUID,ItemStack[]> contents=new ConcurrentHashMap<UUID,ItemStack[]>(); private final Map<UUID,ItemStack[]> armor=new ConcurrentHashMap<UUID,ItemStack[]>(); public StaffManager(){instance=this;} public static StaffManager getInstance(){return instance;} public boolean isFrozen(Player p){return frozen.contains(p.getUniqueId());} public void freeze(Player p, boolean state){ if(state) frozen.add(p.getUniqueId()); else frozen.remove(p.getUniqueId()); }
 public void toggleMod(Player p){ if(modMode.remove(p.getUniqueId())){ p.getInventory().setContents(contents.remove(p.getUniqueId())); p.getInventory().setArmorContents(armor.remove(p.getUniqueId())); for(Player o:Bukkit.getOnlinePlayers()) o.showPlayer(p); p.sendMessage("§cMod mode disabled."); } else { modMode.add(p.getUniqueId()); contents.put(p.getUniqueId(),p.getInventory().getContents()); armor.put(p.getUniqueId(),p.getInventory().getArmorContents()); p.getInventory().clear(); p.getInventory().setArmorContents(null); p.getInventory().setItem(0,new ItemStack(Material.COMPASS)); p.getInventory().setItem(1,new ItemStack(Material.ICE)); p.getInventory().setItem(2,new ItemStack(Material.BOOK)); p.getInventory().setItem(3,new ItemStack(Material.CARPET)); for(Player o:Bukkit.getOnlinePlayers()) if(!o.hasPermission("lynx.staff")) o.hidePlayer(p); p.sendMessage("§aMod mode enabled."); } p.updateInventory(); } }
